329	// genExpr generates IR for an expression and returns the operand
330	func (g *Generator) genExpr(node *ast.Node) (Operand, error) {
331		if node == nil {
332			return Operand{}, fmt.Errorf("nil expression")
333		}
334	
335		switch node.Kind {
336		case ast.NodeIntLit:
337			// Parse integer literal
338			var val int64
339			fmt.Sscanf(node.Value, "%d", &val)
340			return Operand{IsImm: true, ImmVal: val}, nil
341	
342		case ast.NodeIdent:
343			return Operand{Name: node.Value}, nil
344	
345		case ast.NodeBinaryExpr:
346			return g.genBinaryExpr(node)
347	
348		case ast.NodeCallExpr:
349			return g.genCallExpr(node)
350	
351		case ast.NodeFieldAccess:
352			return g.genFieldAccess(node)
353	
354		default:
355			return Operand{}, fmt.Errorf("unsupported expression kind: %d", node.Kind)
356		}
357	}
358	
359	// genBinaryExpr generates IR for a binary expression
360	func (g *Generator) genBinaryExpr(node *ast.Node) (Operand, error) {
361		if len(node.Children) < 2 {
362			return Operand{}, fmt.Errorf("binary expression requires 2 operands")
363		}
364	
365		left, err := g.genExpr(node.Children[0])
366		if err != nil {
367			return Operand{}, err
368		}
369	
370		right, err := g.genExpr(node.Children[1])
371		if err != nil {
372			return Operand{}, err
373		}
374	
375		result := g.newTemp()
376		op := g.opcodeFromOp(node.Value)
377	
378		g.emit(Instruction{
379			Op:   op,
380			Dest: result,
381			Src1: left,
382			Src2: right,
383		})
384	
385		return result, nil
386	}
387	
388	// genCallExpr generates IR for a function call
389	func (g *Generator) genCallExpr(node *ast.Node) (Operand, error) {
390		if len(node.Children) == 0 {
391			return Operand{}, fmt.Errorf("call expression requires function name")
392		}
393	
394		fnName := node.Children[0].Value
395	
396		// Special handling for syscall
397		if fnName == "syscall" {
398			if len(node.Children) < 2 {
399				return Operand{}, fmt.Errorf("syscall requires at least syscall number")
400			}
401	
402			// syscall number (always first arg after function name)
403			numOp, err := g.genExpr(node.Children[1])
404			if err != nil {
405				return Operand{}, err
406			}
407	
408			// Additional args (starting from index 2)
409			for i := 2; i < len(node.Children); i++ {
410				argOp, err := g.genExpr(node.Children[i])
411				if err != nil {
412					return Operand{}, err
413				}
414				g.emit(Instruction{
415					Op:   OpParam,
416					Src1: argOp,
417				})
418			}
419	
420			// Emit syscall instruction
421			result := g.newTemp()
422			g.emit(Instruction{
423				Op:   OpSyscall,
424				Dest: result,
425				Src1: numOp,
426			})
427	
428			return result, nil
429		}
430	
431		// Emit parameters for regular function calls
432		for i := 1; i < len(node.Children); i++ {
433			argOp, err := g.genExpr(node.Children[i])
434			if err != nil {
435				return Operand{}, err
436			}
437			g.emit(Instruction{
438				Op:   OpParam,
439				Src1: argOp,
440			})
441		}
442	
443		// Emit call
444		result := g.newTemp()
445		g.emit(Instruction{
446			Op:   OpCall,
447			Dest: result,
448			Fn:   fnName,
449		})
450	
451		return result, nil
452	}
