454	// Helper functions
455	
456	func (g *Generator) newTemp() Operand {
457		temp := Operand{
458			IsTemp: true,
459			Name:   fmt.Sprintf("t%d", g.tempCount),
460		}
461		g.tempCount++
462		return temp
463	}
464	
465	func (g *Generator) newLabel(prefix string) string {
466		label := fmt.Sprintf("L_%s_%d", prefix, g.labelCount)
467		g.labelCount++
468		return label
469	}
470	
471	func (g *Generator) emit(instr Instruction) {
472		if g.currentFn != nil {
473			g.currentFn.Body = append(g.currentFn.Body, instr)
474		} else {
475			g.program.Main = append(g.program.Main, instr)
476		}
477	}
