130	// CommonSubexpressionRule eliminates redundant computations
131	var CommonSubexpressionRule OptimizationRule
132	
133	func initCommonSubexpressionRule() {
134		CommonSubexpressionRule = OptimizationRule{
135			Name:          "CommonSubexpressionElimination",
136			TargetPattern: profiler.PatternRepeatedSubExpr,
137			Priority:      50,
138			Description:   "Cache results of repeated sub-expressions",
139			Apply: func(node *ast.Node) *ast.Node {
140				if node == nil {
141					return node
142				}
143	
144				for i, child := range node.Children {
145					node.Children[i] = CommonSubexpressionRule.Apply(child)
146				}
147	
148				return node
149			},
150		}
151	}
