206	// parseIntLiteral converts a string to int64
207	func parseIntLiteral(s string) int64 {
208		var result int64
209		for _, c := range s {
210			if c >= '0' && c <= '9' {
211				result = result*10 + int64(c-'0')
212			}
213		}
214		return result
215	}
216	
217	// formatInt converts int64 back to string
218	func formatInt(n int64) string {
219		if n == 0 {
220			return "0"
221		}
222		var result string
223		neg := n < 0
224		if neg {
225			n = -n
226		}
227		for n > 0 {
228			result = string(byte(n%10)+'0') + result
229			n /= 10
230		}
231		if neg {
232			result = "-" + result
233		}
234		return result
235	}
